(window.TNQ=window.TNQ||[]).push({"terms":{"상담구조화":{"d":"상담 시간, 비밀보장, 상담자와 내담자의 역할과 절차를 안내하고 합의하는 과정이다.","r":[]},"전의식":{"d":"평소에는 의식하지 못하지만 주의를 기울이면 쉽게 떠올릴 수 있는 마음의 영역입니다.","r":["방어기제"]},"방어기제":{"d":"불안을 줄이기 위해 무의식적으로 현실을 왜곡하거나 감정을 처리하는 자아의 방식이다.","r":[]},"현실원리":{"d":"욕구 충족을 현실의 조건에 맞게 미루거나 조절하는 자아의 작동 원리입니다.","r":[]},"자기실현경향성":{"d":"인간이 가진 잠재력을 건설적인 방향으로 실현하려는 선천적 성향으로, 로저스 이론의 핵심 개념이다.","r":[]},"자기개념":{"d":"자신의 특성과 역할에 대해 스스로 갖는 지각과 평가입니다.","r":["자기실현경향성"]},"무조건적 긍정적 존중":{"d":"내담자를 조건 없이 있는 그대로 존중하고 수용하는 상담자의 태도이다.","r":[]},"공감적 이해":{"d":"내담자의 내면 경험을 그의 관점에서 정확히 이해하고 전달하는 태도입니다.","r":["무조건적 긍정적 존중"]},"직면":{"d":"내담자의 말과 행동 사이 또는 언어와 비언어 사이의 모순을 지적해 통찰을 유도하는 기법이다.","r":[]},"핵심신념":{"d":"자신과 세상에 대한 가장 깊은 신념으로, 개인이 어떻게 생각하고 느끼고 행동하는지의 기본이 된다.","r":[]},"중간신념":{"d":"핵심신념에서 나온 태도, 규칙, 기대, 가정이다.","r":[]},"고객형 내담자":{"d":"해결중심 상담에서 문제 해결을 원하고 변화에 적극적이며 과제를 수행할 수 있는 내담자 유형이다.","r":[]},"중다양식치료":{"d":"라자루스가 행동, 정서, 감각, 심상, 인지, 대인관계, 약물과 생물학의 일곱 양식으로 내담자를 평가하는 치료이다. 약어는 BASIC ID이다.","r":[]},"범이론적 변화단계모델":{"d":"프로차스카와 디클레멘티가 행동 변화를 계획 전, 계획, 준비, 실행, 유지 단계로 설명한 모델이다.","r":[]},"기술적 통합":{"d":"이론적 배경과 관계없이 효과가 입증된 기법을 골라 쓰는 통합 방식이다.","r":[]},"이론적 통합":{"d":"둘 이상의 이론에서 최상의 개념을 종합해 새로운 개념적 틀을 만드는 통합 방식이다.","r":[]},"동화적 통합":{"d":"한 이론을 중심에 두고 다른 이론의 기법을 받아들여 흡수하는 통합 방식이다.","r":[]},"공통요인적 접근":{"d":"여러 상담 이론에 공통으로 작용하는 치료 효과 요인에 초점을 두는 통합 방식이다.","r":[]},"혼합주의":{"d":"체계적 기준 없이 여러 기법을 절충해 쓰는 것으로, 통합적 상담의 낮은 단계 특징이다.","r":[]},"정서중심치료":{"d":"그린버그가 인간중심, 게슈탈트, 실존주의에 뿌리를 두고 정립한 치료로, 정서를 변화의 핵심으로 본다.","r":[]},"변증법적 행동치료":{"d":"리네한이 경계선 성격장애와 만성적 자살 위험이 있는 내담자를 위해 개발한 치료로, 수용과 변화의 균형, 마음챙김을 강조한다.","r":[]},"마음챙김":{"d":"지금 이 순간의 경험을 판단 없이 알아차리는 훈련이다.","r":[]},"수용전념치료":{"d":"인지적 탈융합과 마음챙김, 가치 탐색, 전념 행동으로 심리적 유연성을 높이는 치료로 ACT라고 한다.","r":[]},"인지적 탈융합":{"d":"자신의 생각과 감정을 사실로 받아들이지 않고 한 걸음 떨어져 바라보는 수용전념치료의 기법이다.","r":[]},"인지왜곡":{"d":"벡이 제시한 개념으로, 현실을 정확하지 않게 해석하는 사고 오류이다.","r":[]},"파국화":{"d":"일어날 일을 최악으로 확대해 예상하는 인지왜곡이다.","r":[]},"과잉일반화":{"d":"한두 번의 사건으로 전반적인 결론을 내리는 인지왜곡이다.","r":[]},"정신적 여과":{"d":"상황의 한 부분만 골라 그것에 집중하는 인지왜곡이다.","r":[]},"개인화":{"d":"관계가 불분명한 일을 자기 탓으로 돌리는 인지왜곡이다.","r":[]},"잘못된 명명":{"d":"한 가지 행동을 근거로 자신이나 타인에게 부정적 이름표를 붙이는 인지왜곡이다.","r":[]},"자동적 사고":{"d":"어떤 상황에서 저절로 빠르게 떠오르는 생각으로, 비판 없이 사실처럼 받아들여진다.","r":[]},"인지도식":{"d":"과거 경험을 일반화한 인지적 구조로, 자신과 세상에 대한 신념으로 이루어진다.","r":[]},"자극포화법":{"d":"싫어하는 자극을 싫증날 때까지 계속 제시해 문제행동을 줄이는 기법이다.","r":[]},"내파법":{"d":"불안 자극을 상상으로 극단적으로 경험하게 하여 불안 반응을 소거하는 기법이다.","r":[]},"홍수법":{"d":"두려운 자극에 직접 오래 노출시켜 불안을 소거하는 기법이다.","r":[]},"타임아웃":{"d":"문제행동이 일어났을 때 강화 받을 수 있는 환경에서 일정 시간 격리하는 기법이다.","r":[]},"소거":{"d":"강화를 중단하여 행동의 빈도를 줄이는 것이다.","r":[]},"용암법":{"d":"촉구를 점차 줄여 가며 독립적인 수행으로 이끄는 기법이다.","r":[]},"토큰 경제":{"d":"바람직한 행동에 토큰을 주고 나중에 원하는 것과 교환하게 하는 기법이다.","r":[]},"반응대가":{"d":"바람직하지 않은 행동을 하면 이미 가진 강화물을 잃게 하는 처벌 방법이다.","r":[]},"과잉교정":{"d":"문제행동을 한 뒤 그 결과를 원상 이상으로 바로잡게 하는 기법이다.","r":[]},"내현적 모델링":{"d":"모델을 볼 수 없을 때 내담자가 모델의 행동을 머릿속에 그려 보게 하는 기법이다.","r":[]},"해결중심 상담":{"d":"문제의 원인보다 해결과 내담자의 강점, 자원에 초점을 두고 질문기법으로 변화를 이끄는 상담이다.","r":[]},"예외질문":{"d":"문제가 일어나지 않았던 때를 찾아 해결의 단서로 삼는 해결중심 질문이다.","r":[]},"대처질문":{"d":"어려운 상황을 어떻게 견뎌 왔는지 물어 내담자의 자원을 확인하는 해결중심 질문이다.","r":[]},"기적질문":{"d":"문제가 해결된 모습을 상상하게 해 목표를 구체화하는 해결중심 질문이다.","r":[]},"척도질문":{"d":"현재 상태나 변화 정도를 숫자로 평가하게 하는 해결중심 질문이다.","r":[]},"관계성질문":{"d":"다른 사람의 관점에서 변화를 상상하게 하는 해결중심 질문이다.","r":[]},"악몽질문":{"d":"기적질문 등이 효과가 없을 때, 문제가 더 악화되는 상황을 떠올리게 하는 질문이다.","r":[]},"접수면접":{"d":"상담 초기에 내담자의 기본 정보와 호소 문제를 확인하고 적합한 상담자에게 연결하는 면접이다.","r":[]},"사례개념화":{"d":"내담자의 문제 발생 배경, 자원과 취약점, 상담목표와 계획을 종합적으로 이해하는 작업이다.","r":[]},"재진술":{"d":"내담자가 말한 내용을 상담자가 다른 말로 간단히 되돌려 주는 기법이다.","r":[]},"명료화":{"d":"내담자의 모호한 표현을 구체적으로 밝혀 주는 기법이다.","r":[]},"해석":{"d":"내담자가 말한 것의 의미와 원인을 새로운 관점에서 설명해 주는 기법이다.","r":[]},"자기노출":{"d":"상담자가 자신의 경험이나 감정을 내담자에게 적절히 공개하는 기법으로, 동질감과 모델링에 쓰인다.","r":[]},"합리적 정서행동상담":{"d":"엘리스가 비합리적 신념이 정서 문제를 일으킨다고 보고 ABCDE 모델로 논박하는 상담이다. REBT라고 한다.","r":[]},"ABCDE 모델":{"d":"REBT에서 촉발사건, 신념, 결과, 논박, 효과의 순서로 정서 문제를 설명하는 틀이다.","r":[]},"비합리적 신념":{"d":"논리성, 현실성, 실용성이 없어 정서 문제를 일으키는 경직된 신념이다.","r":[]},"현실치료":{"d":"글래서의 선택이론에 근거해 인간이 자신의 행동을 선택한다고 보고 현재의 책임 있는 행동에 초점을 두는 상담이다.","r":[]},"선택이론":{"d":"인간이 생존, 사랑과 소속, 힘, 자유, 즐거움의 욕구를 충족하려고 행동을 선택한다고 설명하는 현실치료의 이론이다.","r":[]},"전행동":{"d":"현실치료에서 행동하기, 생각하기, 느끼기, 생리 반응이 함께 일어나는 전체 행동이다.","r":[]},"WDEP모델":{"d":"현실치료에서 바람, 행동, 평가, 계획을 차례로 다루는 상담 절차이다.","r":[]},"승화":{"d":"받아들여지기 어려운 충동을 사회적으로 인정되는 활동으로 바꾸는 방어기제이다.","r":[]},"훈습":{"d":"정신분석에서 통찰을 반복해 다루며 실생활의 변화로 이어 가는 과정이다.","r":[]},"전이":{"d":"내담자가 과거 중요한 인물에게 가졌던 감정과 태도를 상담자에게 옮기는 현상이다.","r":[]},"개인심리학":{"d":"아들러의 이론으로, 열등감 보상과 공동체 의식, 생활양식을 중시한다.","r":[]},"생활양식":{"d":"아들러 이론에서 개인이 삶의 과제를 대하는 일관된 방식이다.","r":[]},"수프에 침 뱉기":{"d":"자기패배적 행동의 숨은 동기를 드러내 그 행동의 매력을 없애는 아들러 기법이다.","r":[]},"단추 누르기":{"d":"즐거운 경험과 불쾌한 경험을 번갈아 떠올리게 해 감정이 자신의 선택임을 깨닫게 하는 아들러 기법이다.","r":[]},"공동체 의식":{"d":"아들러 이론에서 타인과 사회에 관심을 가지고 공헌하려는 마음이다. 결여되면 부적응의 원인이 된다.","r":[]},"실존주의 상담":{"d":"죽음, 자유, 고독, 무의미 같은 궁극적 관심사를 다루며 내담자가 자신의 삶을 책임지도록 돕는 상담이다.","r":[]},"실존적 불안":{"d":"죽음, 고립, 무의미, 자유와 책임이라는 인간 존재 조건에서 비롯되는 불안이다.","r":[]},"가치의 조건":{"d":"타인에게 인정받기 위해 지켜야 한다고 내면화한 조건으로, 자기개념과 유기체적 경험의 불일치를 만든다.","r":[]},"유기체적 경험":{"d":"개인이 실제로 느끼고 경험하는 것 전체로, 자기개념과 일치하지 않을 때 부적응이 생긴다.","r":[]},"게슈탈트 상담":{"d":"펄스가 지금-여기에서의 알아차림과 접촉을 강조하며 미해결 과제와 접촉경계 혼란을 다루는 상담이다.","r":[]},"알아차림":{"d":"자신의 욕구와 감정, 환경을 지금 이 순간 자각하는 것이다.","r":[]},"접촉경계":{"d":"개인과 환경이 만나는 경계로, 이것이 혼란되면 부적응이 생긴다.","r":[]},"교류분석":{"d":"번이 개발한 이론으로, 자아상태, 교류, 게임, 각본을 분석하여 변화를 돕는 상담이다.","r":[]},"이면교류":{"d":"겉으로 드러난 메시지와 숨은 메시지가 동시에 오가는 교류이다.","r":[]},"교차교류":{"d":"상대가 기대한 자아상태와 다른 자아상태로 반응해 대화가 어긋나는 교류이다.","r":[]},"라켓":{"d":"교류분석에서 어려울 때마다 경험하는 익숙하고 불쾌한 감정으로, 초기 결정을 확증하는 과정이다.","r":[]},"이중관계":{"d":"상담자가 내담자와 상담 관계 외에 다른 사적 관계를 맺는 것으로, 피해야 한다.","r":[]},"비밀유지":{"d":"상담에서 알게 된 내용을 내담자 동의 없이 공개하지 않는 윤리 원칙으로, 자해 의도, 아동학대, 법원 요구에는 예외가 있다.","r":[]},"여성주의 상담":{"d":"성차별과 사회 구조의 영향을 다루며 상담관계의 평등과 내담자의 힘 회복을 목표로 하는 상담이다.","r":[]}},"notes":{"2인 이상의 내담자를 동시에 상담하기도 한다":"집단상담이나 가족상담처럼 한 번에 여러 내담자를 함께 만나는 형태도 있습니다.","object constancy":"대상항상성을 가리키는 영어 용어로, 대상이 눈앞에 없어도 변하지 않고 존재한다고 믿는 능력입니다.","transitional object":"과도적 대상을 가리키는 영어 용어로, 위니컷이 어머니에게서 분리되는 과정에서 아이가 쓰는 물건에 붙인 이름입니다.","‘내가 원하는 대로 일이 풀리지 않는 것은 끔찍하다.’":"원하는 대로 안 되면 견딜 수 없다고 과장하는 끔찍화로, 대표적인 비합리적 신념입니다.","‘잘 알지 못함(not-knowing)’의 자세를 취하고 내담자를 전문가로 여긴다":"상담자는 답을 안다고 가정하지 않고 자기 삶에 대해서는 내담자가 가장 잘 안다고 봅니다.","‘지금-여기’에서 경험하는 것들에 초점을 맞춘다":"게슈탈트 상담은 과거나 미래보다 지금 이 순간 느끼고 알아차리는 것을 중심에 둡니다.","개인-체제 간 균형잡힌 관점으로 문제의 원인을 개념화한다":"문제를 개인의 결함으로만 보지 않고 개인과 사회 체제 양쪽에서 원인을 찾습니다.","개인의 행동을 이해하기 위해 어린 시절의 경험을 탐색한다":"지금의 행동은 어린 시절에서 비롯된다고 보기 때문에 그 시기의 경험을 파고듭니다.","개인이 어떻게 생각하고 느끼고 행동하는지에 대한 기본이 된다":"핵심신념은 사고와 감정과 행동을 만들어 내는 가장 밑바닥의 바탕입니다.","검증되지 않고 훈련받지 않은 상담기법의 오ㆍ남용을 하지 않도록 유의한다":"효과가 확인되지 않았거나 배우지 않은 기법을 함부로 쓰면 내담자에게 해가 될 수 있습니다.","고객형 내담자에게 관찰 또는 행동 과제를 부여한다":"변화에 적극적인 고객형에게는 행동으로 옮길 과제를 주고 불평형에게는 관찰 과제를 줍니다.","고전적 조건형성과 상호제지원리를 토대로 하였다":"불안과 이완은 동시에 일어날 수 없다는 원리에 따라 불안 반응을 이완으로 대체합니다.","곰 인형, 담요 등이 그 역할을 한다":"아이가 엄마와 떨어져 있을 때 불안을 달래 주는 애착 물건이 과도적 대상입니다.","과거경험을 일반화한 인지적 구조로":"인지도식이 과거 경험이 쌓여 만들어진 틀이라는 설명의 앞부분입니다.","교통법규를 위반했을 때 내는 과태료":"잘못된 행동을 하면 가진 것을 잃게 되므로 그 행동이 줄어드는 반응대가의 일상 예입니다.","궁극적인 목표는 내담자가 온전히 기능하도록 돕는 것이다":"경험에 열려 있고 자신을 신뢰하며 자기답게 살아가는 상태에 이르게 하는 것이 목표입니다.","긍정적 예외상황 탐색, 새로운 해결책 도출에 초점을 둔다":"문제가 덜하거나 없었던 순간을 찾아 거기서 해결 방법을 이끌어 냅니다.","기적질문, 예외질문 등이 효과가 없을 때 주로 사용된다":"앞선 질문에 막혔을 때 문제가 더 나빠진 상황을 상상하게 하여 돌파구를 찾는 질문입니다.","남성과 여성의 성역할 및 행동의 차이는 사회화에 기인한 것으로 본다":"성별에 따른 행동 차이는 타고난 것이 아니라 자라면서 배운 결과라고 설명합니다.","내담자가 강점 인식 및 자기 옹호를 배우도록 조력한다":"자신의 강점을 알고 필요할 때 자기 권리를 스스로 주장하는 방법을 익히게 합니다.","내담자가 실존적 삶을 살아가도록 돕는다":"책임을 지고 자기 삶을 능동적으로 선택하며 살게 하는 것이 목표입니다.","내담자가 원하는 것을 상담목표로 설정한다":"내담자가 바라는 변화를 목표로 삼아야 상담에 참여하려는 동기가 생깁니다.","내담자가 중요하다고 생각하는 것을 상담목표로 세운다":"상담자의 판단이 아니라 내담자에게 의미 있는 것을 목표로 정합니다.","내담자가 회피하려는 행동을 직면시킨다":"피하고 싶어 하는 감정이나 행동을 마주하게 하여 알아차림을 높입니다.","내담자가 힘을 회복하여 자신의 권리를 지킬 수 있도록 한다":"위축되었던 내담자가 힘을 되찾아 부당한 일에 맞설 수 있게 돕는 임파워먼트의 방향입니다.","내담자에게 필요한 자원 및 지지 제공을 위해":"내담자에게 필요한 자원과 지지를 마련하기 위해 어떻게 하는지 설명하는 문장의 앞부분입니다.","내담자에 대한 진실성, 무조건적 긍정적 존중, 공감적 이해를 중시한다":"인간중심 상담자는 꾸밈없이 대하고 조건 없이 존중하며 내담자의 입장에서 이해하려 합니다.","내담자의 긍정적인 변화와 성장을 목표로 한다":"문제를 없애는 데 그치지 않고 내담자가 좋은 방향으로 변하고 자라는 것을 지향합니다.","내담자의 문제를 유발한 사회ㆍ문화적 요인에 초점을 맞춘다":"고민이 개인 탓이 아니라 사회와 문화의 영향에서 생긴 면이 있는지 짚어 봅니다.","내담자의 의사결정과 문제해결을 돕는 활동":"상담은 내담자가 스스로 결정하고 문제를 풀어 가도록 곁에서 돕는 활동입니다.","내담자의 자기인식과 문제해결을 돕기 위해 다양한 실험을 활용한다":"빈 의자 기법 같은 시도를 통해 내담자가 스스로 깨달음을 얻게 합니다.","내담자의 장점과 자원을 확인하고 지지한다":"내담자가 가진 강점을 찾아 인정해 주면서 해결 의지를 북돋웁니다.","내담자의 적극적인 참여를 필요로 한다":"변화를 만드는 주체는 내담자이므로 내담자가 상담에 직접 참여해야 효과가 납니다.","내담자 자신의 경험과 판단을 신뢰하도록 격려한다":"외부 기준에 기대지 않고 자기가 겪고 판단한 바를 믿도록 힘을 실어 줍니다.","다양한 정체성을 가진 위험ㆍ취약 집단 여성에 주목한다":"성별 외에 계층과 인종 등 여러 정체성이 겹쳐 더 취약한 여성들을 눈여겨봅니다.","다이어트를 위해 친구들과 만나는 약속을 자제하는 것":"음식 유혹이 있는 상황을 일부러 피해 문제 행동의 단서를 줄이는 자극통제의 예입니다.","대면 상담으로만 이루어지는 것은 아니다":"전화나 인터넷 같은 방식으로도 상담이 이루어질 수 있습니다.","매우 빠르게 의식 속을 지나간다":"자동적 사고는 알아차리기 어려울 만큼 순식간에 스쳐 지나가는 생각입니다.","모델링 학습의 목적으로 사용한다":"상담자가 자신의 대처 방식을 보여 주면 내담자가 그것을 보고 배울 수 있습니다.","모델을 관찰할 수 없을 때, 내담자가 모델의 행동을 시각적으로 떠올려 보도록 하는 기법이다":"실제 모델을 볼 수 없는 상황에서 상상 속의 모델 행동을 보며 배우게 하는 기법입니다.","모든 인간은 자기실현경향성을 가지고 태어난다":"로저스는 사람이 누구나 성장하려는 힘을 타고난다고 믿어 상담자가 이 힘을 믿고 돕습니다.","문제 해결에 필요한 자원을 내담자 자신이 갖고 있다고 본다":"해결의 열쇠는 이미 내담자 안에 있다는 전제로 상담을 진행합니다.","법원의 정보공개 요청 사실을 내담자에게 알리고 최소한의 정보를 법원에 제공하였다":"법원이 요청해도 내담자에게 먼저 알리고 필요한 최소한의 정보만 내주는 것이 윤리에 맞는 대응입니다.","변화가능성과 도전을 위한 용기를 불어넣고자 할 때 사용한다":"상담자도 어려움을 넘겼다는 이야기를 들으면 내담자가 변할 수 있다는 힘을 얻습니다.","불안을 느끼게 되면 방어기제가 작동된다":"위협을 느끼면 자아는 불안을 줄이려고 억압이나 투사 같은 방어기제를 쓰게 됩니다.","사실인 것처럼 무비판적으로 받아들이게 된다":"스치는 생각을 따져 보지 않고 곧바로 진실로 믿어 버리는 경향이 있습니다.","삶에 대한 태도, 규범, 기대 등으로 구성된다":"세상을 어떻게 살아야 하는가에 대한 개인의 규칙과 기대가 중간신념의 내용입니다.","상담관계가 올바르게 형성되지 않으면 상담의 효율적 진행은 불가능해진다":"신뢰가 없으면 내담자가 속마음을 말하지 않아 상담 기법을 써도 효과를 내기 어렵습니다.","상담관계를 기초로 상담의 목적을 이루어간다":"상담에서 일어나는 변화는 신뢰할 수 있는 관계 위에서 비로소 가능합니다.","상담관리를 위한 것으로 내담자의 이름과 일련번호가 기록된다":"상담기록부 파일은 내담자를 구분하고 관리하는 용도라서 이름과 번호만 적습니다.","상담 시작에서 종결까지 진행되어 온 상담과정의 요약과 상담 성과의 평가가 포함된다":"종결보고서는 처음부터 끝까지의 흐름을 줄이고 얻은 성과를 평가해 정리한 문서입니다.","상담 신청 시 작성하며 내담자에 관한 최소한의 정보가 수록된다":"상담을 신청하면서 쓰는 서류로, 내담자의 기본 정보만 담깁니다.","상담에 오기 전 변화에 대해 질문한다":"상담을 예약한 뒤 첫 만남 사이에 이미 나아진 점이 있었는지 묻는 질문입니다.","상담의 진행과정을 기록한 문서이다":"상담회기보고서는 회기마다 어떤 이야기가 오갔는지 남겨 두는 기록입니다.","상담자, 내담자, 상담관계가 상담의 주요 구성요소이다":"상담은 돕는 사람과 도움받는 사람, 그리고 둘 사이의 관계 세 가지로 이루어집니다.","상담자는 내담자의 자유로운 감정표현을 허용한다":"비난받지 않는다고 느껴야 내담자가 감정을 숨기지 않으므로 표현을 막지 않습니다.","상담자는 상담에 대한 전문적, 인간적, 윤리적 자질을 갖추어야 한다":"상담자는 지식과 기술뿐 아니라 인품과 윤리 의식도 함께 갖춰야 합니다.","상담자는 지시적이고 적극적인 역할을 수행한다":"비합리적 신념을 직접 반박하고 과제를 주는 등 주도적으로 개입합니다.","상담자와 내담자가 대등한 위치에서 상담에 참여하는 것이 바람직하다":"상담자가 위에서 지시하는 관계가 아니라 서로 동등한 자리에서 협력하는 관계를 지향합니다.","상담자와 내담자 간 동질감을 형성하게 한다":"상담자가 비슷한 경험을 밝히면 내담자가 이해받는다고 느끼며 가까움을 얻습니다.","상담자와 내담자의 평등한 관계를 지향한다":"상담자가 권위를 내세우지 않고 내담자와 동등한 협력자로서 함께 일합니다.","상담 종결 후, 상담이 필요한 다른 사안이 발생하면 · 다시 상담을 받을 수 있다":"성과가 있어 끝났더라도 새로운 문제가 생기면 언제든 상담을 다시 받을 수 있다고 알려 줍니다.","성적 추동은 인간의 가장 기본적인 욕구이다":"프로이트는 성적 에너지를 인간 행동을 이끄는 가장 근원적인 힘으로 보았습니다.","양육자에 대한 일관된 상을 유지할 수 있는 능력을 의미한다":"엄마가 화를 내도 사랑해 주는 엄마라는 상을 지키는 것처럼 일관된 이미지를 간직하는 능력입니다.","여성의 삶의 맥락에 주목한다":"여성주의 상담은 여성이 처한 사회적 조건과 삶의 배경을 먼저 헤아립니다.","여성이 사회적으로 여전히 존재하는 성차별주의와 분투 중이라 본다":"여성이 여전히 사회의 성차별 구조 속에서 어려움을 겪고 있다고 이해합니다.","외적 대상에 대해 갖는 이미지, 감정, 생각, 기억 등을 의미한다":"실제 인물이 곁에 없어도 마음속에 남아 영향을 주는 그 사람의 표상입니다.","유기체적 경험과 자기개념 간의 불일치는 심리적 부적응의 원인이다":"몸으로 느끼는 실제 경험과 자기에 대한 생각이 어긋나면 불안과 부적응이 생깁니다.","의식수준을 의식, 전의식, 무의식으로 구분한다":"프로이트는 마음을 알아차리는 정도에 따라 세 층으로 나누어 설명했습니다.","인간에 대한 결정론적 입장을 취한다":"정신분석은 인간의 행동이 이미 정해진 원인에 의해 일어난다고 보고 자유의지를 제한적으로 봅니다.","인간은 과거 경험에 영향을 받는 존재이다":"현재의 성격과 행동은 어릴 때 겪은 일에서 비롯된다는 관점입니다.","인간은 합리적인 동시에 비합리적인 존재이다":"엘리스는 사람이 합리적으로 생각할 능력과 비합리적으로 생각하는 경향을 모두 지닌다고 보았습니다.","인간행동은 생물학적인 본능과 충동에 의해 동기화 된다":"사람이 움직이는 원동력은 타고난 본능적 충동이라고 보는 프로이트의 생각입니다.","자가치료(self-treatment)의 철학을 강조한다":"상담이 끝난 뒤에도 내담자가 스스로 자신의 생각을 점검하고 다룰 수 있게 하는 것이 목적입니다.","자기공개, 자기노출, 자기폭로라고 불린다":"자기개방은 상담자가 자신의 경험이나 감정을 내담자에게 밝히는 것으로 여러 이름으로 불립니다.","자기의 능력 및 기법의 한계를 인식하고, 전문적 기준에 위배되는 활동을 하지 않는다":"자신이 할 수 있는 범위를 알고 전문가 기준에 어긋나는 일은 하지 않아야 합니다.","자신과 세상 등에 대한 신념으로 구성된다":"도식은 자기 자신과 타인과 세상을 어떻게 보는가에 대한 믿음들로 이루어져 있습니다.","자신을 부정하지 않고 자기 자신으로 존재한다":"자기 감정을 거짓으로 꾸미거나 부정하지 않고 있는 그대로 내담자를 대합니다.","자신의 경험과 자기를 일치시킬 수 있어야 한다":"속으로 느끼는 것과 겉으로 표현하는 모습이 같아야 한다는 뜻입니다.","자신의 능력을 과장하려는 유혹을 성찰하는 것이다":"더 유능해 보이고 싶은 마음이 들 때 그것을 알아차리고 경계해야 합니다.","자신의 전문역할 뒤로 숨지 않는 것을 뜻한다":"전문가라는 가면 뒤에서 방어하지 않고 인간적으로 마주한다는 말입니다.","자아는 현실원리에 따라 본능적 욕구와 외적인 현실 세계를 중재한다":"자아는 원초아의 욕구를 현실에서 허용되는 방식으로 만족시키도록 조절하는 역할을 합니다.","정치적 행동을 취할 필요가 있는 사회 문제를 인식한다":"개인 상담만으로 풀리지 않는 사회 문제는 정치적 행동이 필요하다고 봅니다.","종결단계: 종결에 대한 감정을 다룸":"상담이 끝난다는 사실이 내담자에게 주는 아쉬움과 불안 같은 감정을 다룹니다.","종결을 논하거나 다른 접근방법이나 절차를 강구한다":"성과가 부족할 때는 상담을 마칠지 논의하거나 다른 방식으로 바꾸어 접근합니다.","좋아하는 간식을 주지 않는 엄마의 모든 면을 나쁘다고 보는 아이가 예에 해당한다":"좋음과 나쁨을 한 사람 안에서 통합하지 못하고 한쪽으로만 보는 분열의 예입니다.","중간신념은 핵심신념으로부터 나온 것이다":"신념의 층에서 핵심신념이 더 깊은 바탕이고 중간신념은 그 위에서 생겨납니다.","중기단계: 대안을 찾아 실천":"중기에는 문제를 해결할 방법을 찾고 실제로 행동에 옮기는 데 무게를 둡니다.","지역사회 내 단체, 지도자, 교장 등과 협력한다":"상담실 안에 머물지 않고 지역의 단체와 지도자와 학교와 힘을 합쳐 지원망을 만듭니다.","직접 대면으로 형성되거나 전화, 인터넷, 문자 등의 매체를 통해 형성된다":"상담관계는 마주 앉는 경우뿐 아니라 통신 수단을 쓰는 상담에서도 만들어집니다.","청소년 관련 정책, 규칙, 법규 등에 대해 정통해야 하고 청소년 내담자를 보호하며 내담자가 최선의 발달을 이루도록 노력해야 한다":"청소년 관련 법과 정책을 잘 알고 내담자를 보호하면서 발달을 최대한 돕는 것이 책무입니다.","청소년 기본법에 따라 청소년의 권리와 책임을 다할 수 있게 지원해야 한다":"청소년 상담자는 법이 정한 대로 청소년이 권리를 누리고 책임을 다하도록 돕습니다.","초기단계: 내담자와의 상담관계 형성이 중요, 상담구조화를 실시":"상담 초기에는 신뢰 관계를 만들고 진행 방식을 설명하는 구조화를 합니다.","핵심신념으로부터 나온 태도, 규칙, 기대, 가정 등으로 구성된다":"중간신념은 깊은 믿음에서 파생된 구체적인 규칙과 기대와 조건부 가정 들입니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
